def open_browser_tab(url, **_extra):
    import json, os, datetime, time, uuid
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0200000" if __import__("os").path.isdir("./environment_mix/0200000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "open-browser-tab"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate url
    if not isinstance(url, str):
        out = _err("VALIDATION_ERROR", "url must be a string.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    url_str = url.strip()
    if not url_str:
        out = _err("VALIDATION_ERROR", "url must be a non-empty absolute URL with http/https scheme.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    try:
        p = urlparse(url_str)
    except Exception:
        p = None
    if not p or p.scheme not in ("http", "https") or not p.netloc:
        out = _err("VALIDATION_ERROR", "url must be a non-empty absolute URL with http/https scheme.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    # Resolve context: choose an active session that can actually accept another open tab (<=200)
    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    tabs = _load("browser_tabs.json")
    if not isinstance(tabs, list):
        tabs = []

    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str) and isinstance(s.get("user_id"), str)]
    if not active_sessions:
        out = _err("UNAUTHORIZED", "No active browser session is available for the authenticated user.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    def _open_count_for_session(sid):
        return sum(1 for t in tabs if isinstance(t, dict) and t.get("session_id") == sid and t.get("status") == "open")

    chosen = None
    for s in sorted(active_sessions, key=lambda r: (_parse_dt(r.get("last_seen_at")) or _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at")) or datetime.datetime.min), reverse=True):
        if _open_count_for_session(s.get("id")) < 200:
            chosen = s
            break
    if chosen is None:
        out = _err("QUOTA_EXCEEDED", "Maximum of 200 open tabs per session has been reached.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    session_id = chosen["id"]

    # Compute a unique tab_id_numeric within this session
    used = set()
    for t in tabs:
        if isinstance(t, dict) and t.get("session_id") == session_id:
            v = t.get("tab_id_numeric")
            if isinstance(v, (int, float)) and not isinstance(v, bool):
                try:
                    iv = int(v)
                    if iv > 0 and iv == v:
                        used.add(iv)
                except Exception:
                    pass
    tab_id_numeric = 1
    while tab_id_numeric in used:
        tab_id_numeric += 1

    now = _now_iso()
    tab_row = {
        "id": "bct_" + uuid.uuid4().hex,
        "session_id": session_id,
        "tab_id_numeric": tab_id_numeric,
        "url": url_str,
        "title": None,
        "status": "open",
        "is_active": True,
        "window_id": None,
        "pinned": False,
        "index_in_window": _open_count_for_session(session_id),  # append to end
        "opened_at": now,
        "closed_at": None,
        "created_at": now,
        "updated_at": now,
    }

    # Ensure only one active tab per window/session: deactivate other open tabs (single-window)
    for t in tabs:
        if isinstance(t, dict) and t.get("session_id") == session_id and t.get("status") == "open":
            if t.get("is_active") is True:
                t["is_active"] = False
                t["updated_at"] = now

    tabs.append(tab_row)
    _save("browser_tabs.json", tabs)

    chosen["last_seen_at"] = now
    chosen["updated_at"] = now
    _save("browser_sessions.json", sessions)

    _audit("ok", {"session_id": session_id, "tab_id_numeric": tab_id_numeric})
    return {"tab": tab_row}

def get_list_of_open_tabs(windowId=None, activeOnly=None, includeClosed=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0200000" if __import__("os").path.isdir("./environment_mix/0200000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-list-of-open-tabs"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
        }
        if isinstance(meta, dict) and meta:
            row["meta"] = meta
        logs.append(row)
        _save("request_logs.json", logs)

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or obj.get("v") != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        raw = json.dumps({"v": 1, "offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate params
    if windowId is not None and (isinstance(windowId, bool) or not isinstance(windowId, (int, float)) or int(windowId) != windowId):
        out = _err("VALIDATION_ERROR", "windowId must be an integer-valued number if provided.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    if activeOnly is not None and not isinstance(activeOnly, bool):
        out = _err("VALIDATION_ERROR", "activeOnly must be a boolean if provided.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    if includeClosed is not None and not isinstance(includeClosed, bool):
        out = _err("VALIDATION_ERROR", "includeClosed must be a boolean if provided.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        out = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    if sortBy is None:
        sortBy = "indexInWindow"
    if sortBy not in ("indexInWindow", "openedAt", "updatedAt"):
        out = _err("VALIDATION_ERROR", "sortBy must be one of: indexInWindow, openedAt, updatedAt.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    if sortOrder is None:
        sortOrder = "asc"
    if sortOrder not in ("asc", "desc"):
        out = _err("VALIDATION_ERROR", "sortOrder must be 'asc' or 'desc'.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    off = _decode_cursor(cursor)
    if off is None:
        out = _err("VALIDATION_ERROR", "Invalid cursor.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list):
        sessions = []
    tabs = _load("browser_tabs.json")
    if not isinstance(tabs, list):
        tabs = []

    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str)]
    if not active_sessions:
        out = _err("UNAUTHORIZED", "No active browser session is available for the authenticated user.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    # Choose session that has any tabs (or most), to avoid empty due to wrong context selection
    def _tab_count(sid):
        return sum(1 for t in tabs if isinstance(t, dict) and t.get("session_id") == sid)

    chosen = sorted(active_sessions, key=lambda s: (_tab_count(s["id"]), (_parse_dt(s.get("last_seen_at")) or _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or datetime.datetime.min)), reverse=True)[0]
    sid = chosen["id"]

    includeClosed = bool(includeClosed) if includeClosed is not None else False
    activeOnly = bool(activeOnly) if activeOnly is not None else False

    # Status filter:
    # - if includeClosed True: include open/closing/closed
    # - else: include open/closing (tool-level), but function name implies open tabs; business rule says open only for "get-list-of-open-tabs".
    # We'll implement business rule: default returns only open; includeClosed adds closed; we still exclude "closing" unless includeClosed explicitly wants it.
    if includeClosed:
        allowed_status = {"open", "closing", "closed"}
    else:
        allowed_status = {"open"}

    out_rows = []
    for t in tabs:
        if not isinstance(t, dict):
            continue
        if t.get("session_id") != sid:
            continue
        if t.get("status") not in allowed_status:
            continue
        if windowId is not None:
            if t.get("window_id") is None:
                continue
            if int(t.get("window_id")) != int(windowId):
                continue
        if activeOnly and t.get("is_active") is not True:
            continue
        out_rows.append(t)

    def _sort_key(t):
        if sortBy == "indexInWindow":
            w = t.get("window_id")
            wkey = (1, 0) if w is None else (0, int(w) if isinstance(w, (int, float)) and not isinstance(w, bool) else 0)
            idx = t.get("index_in_window")
            idx = idx if isinstance(idx, int) else 0
            return (wkey[0], wkey[1], idx, str(t.get("id") or ""))
        if sortBy == "openedAt":
            return (_parse_dt(t.get("opened_at")) or datetime.datetime.min, str(t.get("id") or ""))
        # updatedAt
        return (_parse_dt(t.get("updated_at")) or datetime.datetime.min, str(t.get("id") or ""))

    reverse = (sortOrder == "desc")
    out_rows.sort(key=_sort_key, reverse=reverse)

    total = len(out_rows)
    page = out_rows[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    chosen["last_seen_at"] = _now_iso()
    chosen["updated_at"] = chosen["last_seen_at"]
    _save("browser_sessions.json", sessions)

    _audit("ok", {"session_id": sid, "returned": len(page), "total": total})
    return {"tabs": page, "total": total, "has_more": has_more, "next_cursor": next_cursor}

def get_recent_browser_history(searchQuery=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0200000" if __import__("os").path.isdir("./environment_mix/0200000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        try:
            # fromisoformat supports offsets; normalize 'Z'
            s = v.replace("Z", "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(endpoint, status, latency_ms, session_id=None, detail=None):
        # Optional request log if present; do not fail the endpoint if logging fails
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "session_id": session_id,
            "timestamp": _now_iso(),
        }
        if detail is not None:
            row["detail"] = detail
        if isinstance(logs, list):
            logs.append(row)
            _save(fname, logs)

    t0 = time.time()

    # Validate inputs
    if searchQuery is not None and not isinstance(searchQuery, str):
        latency = (time.time() - t0) * 1000
        _audit("get-recent-browser-history", "error", latency, detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "searchQuery must be a string")

    # Resolve ambient auth context: pick any active session that can serve the call
    sessions = _load("browser_sessions.json")
    active_session = None
    for s in sessions if isinstance(sessions, list) else []:
        if isinstance(s, dict) and s.get("status") == "active":
            active_session = s
            break
    if not active_session:
        latency = (time.time() - t0) * 1000
        _audit("get-recent-browser-history", "error", latency, detail={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active browser session available for this user")

    session_id = active_session.get("id")
    items = _load("browser_history_items.json")
    rows = []
    q = searchQuery.strip().lower() if isinstance(searchQuery, str) and searchQuery.strip() else None
    for it in items if isinstance(items, list) else []:
        if not isinstance(it, dict):
            continue
        if it.get("session_id") != session_id:
            continue
        if q:
            url = it.get("url") or ""
            title = it.get("title") or ""
            if q not in str(url).lower() and q not in str(title).lower():
                continue
        rows.append(it)

    # Order by last_visited_at desc
    def _sort_key(r):
        dt = _parse_dt(r.get("last_visited_at"))
        # None sorts last
        return dt if dt is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)

    rows.sort(key=_sort_key, reverse=True)

    latency = (time.time() - t0) * 1000
    _audit("get-recent-browser-history", "ok", latency, session_id=session_id)
    return {
        "historyItems": rows,
        "meta": {"total": len(rows), "session_id": session_id},
    }

def get_tab_web_content(tabId, offset=None, **_extra):
    import json, os, datetime, time, uuid
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0200000" if __import__("os").path.isdir("./environment_mix/0200000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-tab-web-content"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0)
    def _now_iso():
        return _now().isoformat() + "Z"

    def _audit(status_val, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            row = {
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status_val,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
            }
            if isinstance(meta, dict) and meta:
                row["meta"] = meta
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _norm_intish(v, *, allow_none=False):
        if v is None and allow_none:
            return None
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return None
        try:
            iv = int(v)
        except Exception:
            return None
        if float(iv) != float(v):
            return None
        return iv

    def _abs_http_url(u):
        if not isinstance(u, str):
            return None
        s = u.strip()
        if not s:
            return None
        try:
            p = urlparse(s)
        except Exception:
            return None
        if p.scheme not in ("http", "https") or not p.netloc:
            return None
        return s

    tabId_i = _norm_intish(tabId)
    if tabId_i is None or tabId_i <= 0:
        out = _err("VALIDATION_ERROR", "tabId must be a positive integer-valued number.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    if offset is None:
        offset_i = 0
    else:
        offset_i = _norm_intish(offset)
        if offset_i is None or offset_i < 0:
            out = _err("VALIDATION_ERROR", "offset must be an integer-valued number >= 0.")
            _audit("error", {"code": out["error"]["code"]})
            return out

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    snaps = _load("tab_content_snapshots.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(tabs, list): tabs = []
    if not isinstance(snaps, list): snaps = []

    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str)]
    if not active_sessions:
        out = _err("UNAUTHORIZED", "No active browser session is available for this request.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    # Choose a session that actually has the tab open (avoid picking a wrong active session)
    tab_row = None
    session_id = None
    for s in active_sessions:
        sid = s.get("id")
        for t in tabs:
            if not isinstance(t, dict): 
                continue
            if t.get("session_id") != sid:
                continue
            if _norm_intish(t.get("tab_id_numeric")) == tabId_i and t.get("status") == "open":
                tab_row = t
                session_id = sid
                break
        if tab_row:
            break

    if not tab_row:
        # If tab exists but not open in any active session -> NOT_FOUND vs INVALID_TRANSITION?
        # Tool contract says NOT_FOUND if tabId does not exist; business rule says must refer to an open tab.
        # Provide precise rule-based error.
        exists_any = False
        in_active_any = False
        for s in active_sessions:
            sid = s.get("id")
            for t in tabs:
                if isinstance(t, dict) and t.get("session_id") == sid and _norm_intish(t.get("tab_id_numeric")) == tabId_i:
                    exists_any = True
                    in_active_any = True
                    break
            if in_active_any:
                break
        if in_active_any and exists_any:
            out = _err("INVALID_TRANSITION", "tabId must refer to an open tab in the active session (rule: get-tab-web-content requires status='open').", tabId=tabId_i)
        else:
            out = _err("NOT_FOUND", "tabId does not exist in any active session.", tabId=tabId_i)
        _audit("error", {"code": out["error"]["code"]})
        return out

    tab_record_id = tab_row.get("id")
    tab_url = tab_row.get("url")
    if not isinstance(tab_record_id, str):
        out = _err("CONFLICT", "Tab record is missing an internal id; cannot resolve snapshots.", tabId=tabId_i)
        _audit("error", {"code": out["error"]["code"]})
        return out

    tab_url_norm = _abs_http_url(tab_url) or (tab_url.strip() if isinstance(tab_url, str) else "")
    now_iso = _now_iso()

    # Find latest ready snapshot for this tab
    ready = [s for s in snaps if isinstance(s, dict) and s.get("tab_record_id") == tab_record_id and s.get("status") == "ready"]
    def _cv(x):
        v = x.get("content_version")
        return v if isinstance(v, int) else -1
    ready.sort(key=_cv, reverse=True)
    latest = ready[0] if ready else None

    # If no ready snapshot exists or URL has changed, create new snapshot and stale older ready ones
    need_new = False
    if latest is None:
        need_new = True
    else:
        if isinstance(latest.get("url_at_capture"), str) and tab_url_norm and latest.get("url_at_capture") != tab_url_norm:
            need_new = True

    # Transition older ready snapshots to stale when making a new one
    if need_new:
        for s in snaps:
            if isinstance(s, dict) and s.get("tab_record_id") == tab_record_id and s.get("status") == "ready":
                s["status"] = "stale"
                s["updated_at"] = now_iso

        max_ver = 0
        for s in snaps:
            if isinstance(s, dict) and s.get("tab_record_id") == tab_record_id and isinstance(s.get("content_version"), int):
                if s["content_version"] > max_ver:
                    max_ver = s["content_version"]
        new_ver = max_ver + 1 if max_ver >= 0 else 1
        if new_ver < 1:
            new_ver = 1

        # Minimal deterministic extraction (offline): store URL as content; links empty
        text = tab_url_norm if tab_url_norm else ""
        links = []
        snap_id = "tcs_" + uuid.uuid4().hex[:26]

        new_snap = {
            "id": snap_id,
            "tab_record_id": tab_record_id,
            "content_version": new_ver,
            "url_at_capture": tab_url_norm,
            "captured_at": now_iso,
            "status": "ready",
            "text_content": text,
            "text_length": len(text),
            "links": links,
            "mime_type": "text/html",
            "charset": "utf-8",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        snaps.append(new_snap)
        latest = new_snap

        # Retention: at most 20 snapshots per tab; oldest stale -> deleted
        tab_snaps = [s for s in snaps if isinstance(s, dict) and s.get("tab_record_id") == tab_record_id]
        # Order by content_version asc for oldest
        tab_snaps_sorted = sorted(tab_snaps, key=lambda x: x.get("content_version") if isinstance(x.get("content_version"), int) else 0)
        if len(tab_snaps_sorted) > 20:
            to_delete = len(tab_snaps_sorted) - 20
            for s in tab_snaps_sorted:
                if to_delete <= 0:
                    break
                if s.get("status") == "stale":
                    s["status"] = "deleted"
                    s["updated_at"] = now_iso
                    to_delete -= 1

        _save("tab_content_snapshots.json", snaps)

    # Serve paging
    text_content = latest.get("text_content") if isinstance(latest, dict) and isinstance(latest.get("text_content"), str) else ""
    links = latest.get("links") if isinstance(latest, dict) and isinstance(latest.get("links"), list) else []
    text_len = latest.get("text_length") if isinstance(latest, dict) and isinstance(latest.get("text_length"), int) else len(text_content)
    if text_len != len(text_content):
        text_len = len(text_content)

    if offset_i > text_len:
        chunk = ""
    else:
        chunk = text_content[offset_i:]

    has_more = (offset_i + len(chunk)) < text_len if chunk is not None else False
    next_offset = (offset_i + len(chunk)) if has_more else None

    _audit("ok", {"tabId": tabId_i, "snapshotVersion": latest.get("content_version") if isinstance(latest, dict) else None})

    return {
        "tabId": tabId_i,
        "sessionId": session_id,
        "contentVersion": latest.get("content_version") if isinstance(latest, dict) else None,
        "url": tab_url,
        "urlAtCapture": latest.get("url_at_capture") if isinstance(latest, dict) else None,
        "capturedAt": latest.get("captured_at") if isinstance(latest, dict) else None,
        "offset": offset_i,
        "text": chunk,
        "textLength": text_len,
        "links": links,
        "hasMore": bool(has_more),
        "nextOffset": next_offset
    }

def reorder_browser_tabs(tabOrder, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0200000" if __import__("os").path.isdir("./environment_mix/0200000") else "/app/database")
    def _load(n):
