        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "reorder-browser-tabs"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status_val, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status_val,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _norm_intish(v):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return None
        try:
            iv = int(v)
        except Exception:
            return None
        if float(iv) != float(v):
            return None
        return iv

    if not isinstance(tabOrder, list) or len(tabOrder) == 0:
        out = _err("VALIDATION_ERROR", "tabOrder must be a non-empty array of numbers.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    norm = []
    seen = set()
    for x in tabOrder:
        xi = _norm_intish(x)
        if xi is None or xi <= 0:
            out = _err("VALIDATION_ERROR", "tabOrder must contain positive integer-valued numbers.")
            _audit("error", {"code": out["error"]["code"]})
            return out
        if xi in seen:
            out = _err("VALIDATION_ERROR", "tabOrder must not contain duplicates.", duplicateTabId=xi)
            _audit("error", {"code": out["error"]["code"]})
            return out
        seen.add(xi)
        norm.append(xi)

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(tabs, list): tabs = []

    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str)]
    if not active_sessions:
        out = _err("UNAUTHORIZED", "No active browser session is available for this request.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    # Choose session where these tabs are open (avoid wrong session choice)
    chosen_sid = None
    open_by_sid = {}
    for s in active_sessions:
        sid = s.get("id")
        open_tabs = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == sid and t.get("status") == "open"]
        open_by_sid[sid] = open_tabs
        open_ids = {_norm_intish(t.get("tab_id_numeric")) for t in open_tabs}
        open_ids.discard(None)
        # If caller provides only 1 id, allow choosing session where it exists as open
        if set(norm).issubset(open_ids) and len(open_ids) == len(norm):
            # still must match exactly all open tabs per business rule; choose later
            chosen_sid = sid
            break
    if chosen_sid is None:
        # best effort: pick session where at least one provided id exists as open
        for sid, open_tabs in open_by_sid.items():
            open_ids = {_norm_intish(t.get("tab_id_numeric")) for t in open_tabs}
            open_ids.discard(None)
            if any(i in open_ids for i in norm):
                chosen_sid = sid
                break
    if chosen_sid is None:
        chosen_sid = active_sessions[0].get("id")
        open_tabs = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == chosen_sid and t.get("status") == "open"]
    else:
        open_tabs = open_by_sid.get(chosen_sid, [])

    open_ids = []
    by_id = {}
    for t in open_tabs:
        tid = _norm_intish(t.get("tab_id_numeric"))
        if tid is None:
            continue
        open_ids.append(tid)
        by_id[tid] = t

    missing = [tid for tid in norm if tid not in by_id]
    if missing:
        out = _err("NOT_FOUND", "One or more referenced tabIds do not exist as open tabs in the active session.", missingTabIds=missing)
        _audit("error", {"code": out["error"]["code"]})
        return out

    # Business rule: tabOrder must contain each currently open tab exactly once (no missing/extra)
    open_id_set = set(open_ids)
    norm_set = set(norm)
    if norm_set != open_id_set or len(norm) != len(open_ids):
        extra = sorted(list(norm_set - open_id_set))
        missing2 = sorted(list(open_id_set - norm_set))
        out = _err(
            "VALIDATION_ERROR",
            "tabOrder must contain each currently open tab_id_numeric exactly once (rule: reorder-browser-tabs requires a complete ordering).",
            missingOpenTabIds=missing2,
            extraTabIds=extra
        )
        _audit("error", {"code": out["error"]["code"]})
        return out

    now_iso = _now_iso()
    # Single-window implementation: keep window_id as-is; reorder within each window is undefined by caller;
    # but rule says match new order; we'll apply sequential indices globally (common single-window behavior).
    for idx, tid in enumerate(norm):
        tab = by_id[tid]
        tab["index_in_window"] = idx
        tab["updated_at"] = now_iso

    _save("browser_tabs.json", tabs)
    # Return updated open tabs ordered by index_in_window
    updated = [by_id[tid] for tid in norm]
    _audit("ok", {"count": len(updated), "sessionId": chosen_sid})
    return {"sessionId": chosen_sid, "tabs": updated, "meta": {"count": len(updated)}}

