        _audit("error", {"code": out["error"]["code"]})
        return out

    # Rate limit: per tab, 30 per minute based on requested_at
    now = _now()
    one_min_ago = now - datetime.timedelta(seconds=60)
    recent = 0
    for r in highlights:
        if not isinstance(r, dict): 
            continue
        if r.get("tab_record_id") != tab_record_id:
            continue
        ts = _parse_dt(r.get("requested_at"))
        if ts is not None and ts >= one_min_ago:
            recent += 1
    if recent >= 30:
        out = _err("RATE_LIMIT", "Too many highlight requests for this tab (limit: 30 per minute).", tabId=tabId_i, limit=30, windowSeconds=60)
        _audit("error", {"code": out["error"]["code"], "recent": recent})
