    _save("tab_find_highlights.json", highlights)

    # "Execution" offline: use latest ready snapshot; if missing, fail; else count occurrences (case-insensitive)
    ready = [s for s in snaps if isinstance(s, dict) and s.get("tab_record_id") == tab_record_id and s.get("status") == "ready"]
    ready.sort(key=lambda x: x.get("content_version") if isinstance(x.get("content_version"), int) else -1, reverse=True)
    snap = ready[0] if ready else None

    if snap is None or not isinstance(snap.get("text_content"), str):
        record["status"] = "failed"
        record["error_message"] = "DOM snapshot missing (tab navigated)"
        record["updated_at"] = now_iso
        record["match_count"] = None
        _save("tab_find_highlights.json", highlights)
        _audit("ok", {"status": record["status"]})
        return {
            "tabId": tabId_i,
            "sessionId": session_id,
            "requestId": req_id,
            "status": record["status"],
            "matchCount": None,
            "errorMessage": record["error_message"]
        }

    hay = snap["text_content"]
    needle = q
    # Simple count, case-insensitive
    try:
        count = hay.lower().count(needle.lower())
    except Exception:
        count = 0

    if count > 0:
        record["status"] = "applied"
        record["match_count"] = int(count)
    else:
        record["status"] = "not_found"
        record["match_count"] = 0
    record["updated_at"] = now_iso
    _save("tab_find_highlights.json", highlights)

    _audit("ok", {"status": record["status"], "matchCount": record["match_count"]})
    return {
        "tabId": tabId_i,
        "sessionId": session_id,
        "requestId": req_id,
        "status": record["status"],
        "matchCount": record["match_count"],
        "errorMessage": record.get("error_message")
    }

def update_browser_session_status(targetStatus, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0200000" if __import__("os").path.isdir("./environment_mix/0200000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    status_code = "ok"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00").astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now_iso(),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    allowed = {"active": {"inactive", "revoked"}, "inactive": {"active", "revoked"}, "revoked": set()}

    if not isinstance(targetStatus, str) or targetStatus not in ("active", "inactive", "revoked"):
        status_code = "VALIDATION_ERROR"
        out = _err("VALIDATION_ERROR", "Invalid targetStatus.", allowed=["active", "inactive", "revoked"])
        _log("update-browser-session-status", status_code, {"targetStatus": targetStatus})
        return out

    sessions = _load("browser_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Ambient auth: choose a session for some authenticated user that is modifiable (active/inactive).
    # Prefer active, else inactive; choose most recent.
    candidates = [s for s in sessions if isinstance(s, dict) and s.get("status") in ("active", "inactive") and isinstance(s.get("user_id"), str)]
    if not candidates:
        status_code = "NOT_FOUND"
        out = _err("NOT_FOUND", "No active or inactive browser session exists for the caller.")
        _log("update-browser-session-status", status_code, {"targetStatus": targetStatus})
        return out

    def _score(s):
        return _parse_dt(s.get("last_seen_at")) or _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or datetime.datetime.min

    # If any active exists, pick the newest active; else newest inactive.
    actives = [s for s in candidates if s.get("status") == "active"]
    sess = sorted(actives, key=_score, reverse=True)[0] if actives else sorted(candidates, key=_score, reverse=True)[0]

    current = sess.get("status")
    if targetStatus == current:
        # Idempotent: return existing record (still counts as effect? no mutation, but acceptable for idempotent state set).
        out = {"session": sess}
        _log("update-browser-session-status", status_code, {"sessionId": sess.get("id"), "from": current, "to": targetStatus, "idempotent": True})
        return out

    if targetStatus not in allowed.get(current, set()):
        status_code = "INVALID_TRANSITION"
        out = _err("INVALID_TRANSITION", "Session status transition not allowed.", fromStatus=current, toStatus=targetStatus)
        _log("update-browser-session-status", status_code, {"sessionId": sess.get("id"), "from": current, "to": targetStatus})
        return out

    now = _now_iso()
    sess["status"] = targetStatus
    sess["updated_at"] = now
    sess["last_seen_at"] = now

    # created_at <= updated_at constraint: ensure created_at exists; if missing, set to now
    if not isinstance(sess.get("created_at"), str):
        sess["created_at"] = now

    # Persist change
    mutated = False
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == sess.get("id"):
            sessions[i] = sess
            mutated = True
            break
    if not mutated:
        status_code = "NOT_FOUND"
        out = _err("NOT_FOUND", "Session no longer exists.")
        _log("update-browser-session-status", status_code, {"sessionId": sess.get("id"), "from": current, "to": targetStatus})
        return out
    _save("browser_sessions.json", sessions)

    # If revoked, cascade delete dependent rows (hard delete) per rule.
    if targetStatus == "revoked":
        tabs = _load("browser_tabs.json")
        if not isinstance(tabs, list):
            tabs = []
        snaps = _load("tab_content_snapshots.json")
        if not isinstance(snaps, list):
            snaps = []
        highs = _load("tab_find_highlights.json")
        if not isinstance(highs, list):
            highs = []
        hist = _load("browser_history_items.json")
        if not isinstance(hist, list):
            hist = []

        sid = sess.get("id")
        tab_ids = [t.get("id") for t in tabs if isinstance(t, dict) and t.get("session_id") == sid]
        tabs2 = [t for t in tabs if not (isinstance(t, dict) and t.get("session_id") == sid)]
        snaps2 = [r for r in snaps if not (isinstance(r, dict) and r.get("tab_record_id") in set(tab_ids))]
        highs2 = [r for r in highs if not (isinstance(r, dict) and r.get("tab_record_id") in set(tab_ids))]
        hist2 = [r for r in hist if not (isinstance(r, dict) and r.get("session_id") == sid)]

        _save("browser_tabs.json", tabs2)
        _save("tab_content_snapshots.json", snaps2)
        _save("tab_find_highlights.json", highs2)
        _save("browser_history_items.json", hist2)

    out = {"session": sess}
    _log("update-browser-session-status", status_code, {"sessionId": sess.get("id"), "from": current, "to": targetStatus})
    return out

