    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str)]
    if not active_sessions:
        out = _err("UNAUTHORIZED", "No active browser session is available for this request.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    allowed_status = {"open", "closing"} | ({"closed"} if includeClosed else set())

    # Search across active sessions for a matching tab, prefer a session where it exists
    match = None
    match_sid = None
    for s in active_sessions:
        sid = s.get("id")
        for t in tabs:
            if not isinstance(t, dict):
                continue
            if t.get("session_id") != sid:
                continue
            if _norm_intish(t.get("tab_id_numeric")) != tabId_i:
                continue
            if t.get("status") in allowed_status:
                match = t
                match_sid = sid
                break
        if match:
            break

    if not match:
        out = _err("NOT_FOUND", "No matching tab exists in the active session.", tabId=tabId_i)
        _audit("error", {"code": out["error"]["code"]})
        return out

    _audit("ok", {"tabId": tabId_i})
    return {"sessionId": match_sid, "tab": match}

def update_browser_tab(tabId, isActive=None, pinned=None, windowId=None, indexInWindow=None, url=None, **_extra):
    import json, os, datetime, time, uuid
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0200000" if __import__("os").path.isdir("./environment_mix/0200000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update-browser-tab"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status_val, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status_val,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _norm_intish(v, *, allow_none=False):
        if v is None and allow_none:
            return None
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return None
        try:
            iv = int(v)
        except Exception:
            return None
        if float(iv) != float(v):
            return None
        return iv

    def _abs_http_url(u):
        if not isinstance(u, str):
            return None
        s = u.strip()
        if not s:
            return None
        try:
            p = urlparse(s)
        except Exception:
            return None
        if p.scheme not in ("http", "https") or not p.netloc:
            return None
        return s

    tabId_i = _norm_intish(tabId)
    if tabId_i is None or tabId_i <= 0:
        out = _err("VALIDATION_ERROR", "tabId must be a positive integer-valued number.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    if isActive is not None and not isinstance(isActive, bool):
        out = _err("VALIDATION_ERROR", "isActive must be a boolean if provided.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    if pinned is not None and not isinstance(pinned, bool):
        out = _err("VALIDATION_ERROR", "pinned must be a boolean if provided.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    if windowId is not None and windowId is not None and not isinstance(windowId, (int, float)) and windowId is not None:
        # allow null; numbers only otherwise (including integer-valued floats)
        out = _err("VALIDATION_ERROR", "windowId must be a number or null if provided.")
        _audit("error", {"code": out["error"]["code"]})
        return out
    if windowId is not None:
        if windowId is None:
            window_id_val = None
        else:
            window_id_val = _norm_intish(windowId, allow_none=True)
            if window_id_val is None:
                out = _err("VALIDATION_ERROR", "windowId must be an integer-valued number or null.")
                _audit("error", {"code": out["error"]["code"]})
                return out
    else:
        window_id_val = None  # sentinel not used

    if indexInWindow is not None:
        if not isinstance(indexInWindow, int) or indexInWindow < 0:
            out = _err("VALIDATION_ERROR", "indexInWindow must be an integer >= 0 if provided.")
            _audit("error", {"code": out["error"]["code"]})
            return out

    url_norm = None
    if url is not None:
        url_norm = _abs_http_url(url)
        if url_norm is None:
            out = _err("VALIDATION_ERROR", "url must be a non-empty absolute URL with scheme http or https if provided.")
            _audit("error", {"code": out["error"]["code"]})
            return out

    if isActive is None and pinned is None and windowId is None and indexInWindow is None and url is None:
        out = _err("VALIDATION_ERROR", "At least one mutable field must be provided to update.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(tabs, list): tabs = []

    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str)]
    if not active_sessions:
        out = _err("UNAUTHORIZED", "No active browser session is available for this request.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    # Find the tab in any active session (prefer open/closing; allow closed exists but conflict on update)
    found = None
    found_sid = None
    for s in active_sessions:
        sid = s.get("id")
        for t in tabs:
            if not isinstance(t, dict):
                continue
            if t.get("session_id") != sid:
                continue
            if _norm_intish(t.get("tab_id_numeric")) == tabId_i:
                found = t
                found_sid = sid
                break
        if found:
            break

    if not found:
        out = _err("NOT_FOUND", "Tab does not exist in the active session.", tabId=tabId_i)
        _audit("error", {"code": out["error"]["code"]})
        return out

    if found.get("status") == "closed":
        out = _err("CONFLICT", "Cannot update a closed tab.", tabId=tabId_i)
        _audit("error", {"code": out["error"]["code"]})
        return out
    if found.get("status") == "closing":
        # disallow navigation/structural updates while closing
        if url is not None or windowId is not None or indexInWindow is not None:
            out = _err("CONFLICT", "Cannot change url/window/index while tab is closing.", tabId=tabId_i)
            _audit("error", {"code": out["error"]["code"]})
            return out

    now_iso = _now_iso()

    if pinned is not None:
        found["pinned"] = pinned
    if windowId is not None:
        found["window_id"] = window_id_val  # may be None
    if indexInWindow is not None:
        found["index_in_window"] = indexInWindow
    if url is not None:
        # "Navigate": update url, title unknown; also set last_seen_at on session
        found["url"] = url_norm
        found["title"] = found.get("title")  # leave as-is
        # Do not directly mutate snapshots here; get-tab-web-content will detect url change and stale old snapshots.
    if isActive is not None:
        # Make this tab active, and (best-effort) deactivate other open tabs in same session/window
        found["is_active"] = isActive
        if isActive:
            wid = found.get("window_id")
            for t in tabs:
                if not isinstance(t, dict):
                    continue
                if t is found:
                    continue
                if t.get("session_id") != found_sid:
                    continue
                if t.get("status") != "open":
                    continue
                # same window semantics: if window_id missing/null treat as same window when both None
                if t.get("window_id") != wid:
                    continue
                t["is_active"] = False
                t["updated_at"] = now_iso
        else:
            # if deactivating the currently active, allow it; no other changes
            pass

    found["updated_at"] = now_iso
    _save("browser_tabs.json", tabs)
    _audit("ok", {"tabId": tabId_i, "sessionId": found_sid})
    return {"sessionId": found_sid, "tab": found}

def list_tab_content_snapshots(tabId, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0200000" if __import__("os").path.isdir("./environment_mix/0200000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list-tab-content-snapshots"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(status_val, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list): logs = []
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "status": status_val,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now_iso(),
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _norm_intish(v):
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return None
        try:
            iv = int(v)
        except Exception:
            return None
        if float(iv) != float(v):
            return None
        return iv

    tabId_i = _norm_intish(tabId)
    if tabId_i is None or tabId_i <= 0:
        out = _err("VALIDATION_ERROR", "tabId must be a positive integer-valued number.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    if status is not None:
        if not isinstance(status, str) or status not in ("ready", "stale", "deleted"):
            out = _err("VALIDATION_ERROR", "status must be one of: ready, stale, deleted.")
            _audit("error", {"code": out["error"]["code"]})
            return out

    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            out = _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
            _audit("error", {"code": out["error"]["code"]})
            return out
        limit_i = limit

    if cursor is not None and not isinstance(cursor, str):
        out = _err("VALIDATION_ERROR", "cursor must be a string if provided.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    # Cursor is opaque; implement as base64 json {"after": "<snapshot_id>"} or raw id fallback
    after_id = None
    if cursor:
        try:
            decoded = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            decoded_s = decoded.decode("utf-8")
            try:
                obj = json.loads(decoded_s)
                if isinstance(obj, dict) and isinstance(obj.get("after"), str):
                    after_id = obj["after"]
                elif isinstance(obj, str):
                    after_id = obj
                else:
                    after_id = cursor
            except Exception:
                after_id = decoded_s if decoded_s else cursor
        except Exception:
            after_id = cursor

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    snaps = _load("tab_content_snapshots.json")
    if not isinstance(sessions, list): sessions = []
    if not isinstance(tabs, list): tabs = []
    if not isinstance(snaps, list): snaps = []

    active_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "active" and isinstance(s.get("id"), str)]
    if not active_sessions:
        out = _err("UNAUTHORIZED", "No active browser session is available for this request.")
        _audit("error", {"code": out["error"]["code"]})
        return out

    # Find tab in any active session (open/closing/closed all qualify for listing snapshots, but tool says active session)
    tab_row = None
    session_id = None
    for s in active_sessions:
        sid = s.get("id")
        for t in tabs:
            if isinstance(t, dict) and t.get("session_id") == sid and _norm_intish(t.get("tab_id_numeric")) == tabId_i:
                tab_row = t
                session_id = sid
                break
        if tab_row:
            break

    if not tab_row or not isinstance(tab_row.get("id"), str):
        out = _err("NOT_FOUND", "Tab does not exist in the active session.", tabId=tabId_i)
        _audit("error", {"code": out["error"]["code"]})
        return out

    tab_record_id = tab_row["id"]

    items = [s for s in snaps if isinstance(s, dict) and s.get("tab_record_id") == tab_record_id]
    if status is not None:
        items = [s for s in items if s.get("status") == status]

    # Order by content_version desc (most recent first)
    def _cv(x):
        return x.get("content_version") if isinstance(x.get("content_version"), int) else -1
    items.sort(key=_cv, reverse=True)

    # Apply cursor: skip until after_id encountered
    if after_id:
        idx = 0
        while idx < len(items) and items[idx].get("id") != after_id:
            idx += 1
        if idx < len(items) and items[idx].get("id") == after_id:
            items = items[idx + 1:]
        # if after_id not found, treat as starting from beginning (realistic behavior)

    page = items[:limit_i]
    has_more = len(items) > limit_i
    next_cursor = None
    if has_more and page:
        payload = json.dumps({"after": page[-1].get("id")})
        next_cursor = base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    # Metadata only (no text_content)
    out_rows = []
    for s in page:
        out_rows.append({
            "id": s.get("id"),
            "tabRecordId": s.get("tab_record_id"),
            "contentVersion": s.get("content_version"),
            "urlAtCapture": s.get("url_at_capture"),
            "capturedAt": s.get("captured_at"),
            "status": s.get("status"),
            "textLength": s.get("text_length"),
            "mimeType": s.get("mime_type"),
            "charset": s.get("charset"),
            "createdAt": s.get("created_at"),
            "updatedAt": s.get("updated_at"),
        })

    _audit("ok", {"count": len(out_rows), "hasMore": has_more})
    return {
        "sessionId": session_id,
        "tabId": tabId_i,
        "snapshots": out_rows,
        "meta": {
            "limit": limit_i,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "total": len([s for s in snaps if isinstance(s, dict) and s.get("tab_record_id") == tab_record_id and (status is None or s.get("status") == status)])
        }
    }
